/**
 * Reacts to blockers closing: when the last open blocker of an issue goes away, its assignee is told the issue is unblocked.
 *
 * Must call (do not reimplement): subscribe, notify
 */
import { subscribe } from "@/lib/event-bus";
import * as dependencyRepo from "@/server/repositories/issue-dependency-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import { notify } from "./notification-service";
import type { IssueId, OrgId, UserId } from "@/types/common";
import type { IssueStatus } from "@/types/issue";
import type { Unsubscribe } from "@/types/event";

function isClosed(status: IssueStatus): boolean {
  return status === "done" || status === "canceled";
}

export function registerIssueUnblockListeners(): Unsubscribe {
  const offs: Unsubscribe[] = [
    subscribe("issue.status_changed", async (payload) => {
      if (isClosed(payload.from) || !isClosed(payload.to)) return;
      await notifyUnblocked(payload.orgId, payload.issueId, payload.actorId);
    }),
    subscribe("issue.archived", async (payload) => {
      const blocker = await issueRepo.findIssueById(
        payload.orgId,
        payload.issueId,
      );
      if (blocker === null || isClosed(blocker.status)) return;
      await notifyUnblocked(payload.orgId, payload.issueId, payload.actorId);
    }),
  ];

  return () => {
    for (const off of offs) off();
  };
}

/** `blockerId` just went from open to closed; tell whoever it was holding up. */
async function notifyUnblocked(
  orgId: OrgId,
  blockerId: IssueId,
  actorId: UserId | null,
): Promise<void> {
  for (const issueId of await dependencyRepo.listBlockedIds(orgId, blockerId)) {
    const blocked = await issueRepo.findIssueById(orgId, issueId);
    if (blocked === null || blocked.archivedAt !== null) continue;
    if (isClosed(blocked.status) || blocked.assigneeId === null) continue;
    if ((await dependencyRepo.listOpenBlockerIds(orgId, issueId)).length > 0) {
      continue;
    }

    await notify(orgId, "issue_unblocked", [blocked.assigneeId], {
      title: "An issue was unblocked",
      body: `Issue ${blocked.id} has no open blockers left`,
      href: `/issues/${blocked.id}`,
      actorId,
    });
  }
}
